SourceCode.Declaration:
/// <summary>
/// The <c>AVAWHSProcessGuidePromptLicensePlateIdStep</c> class represents the step for viewing License plate
/// details and confirming the same.
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePromptLicensePlateIdStep))
]
class AVAWHSProcessGuidePromptLicensePlateIdStep extends ProcessGuideStep
{
}

Method.Source:
protected final boolean isComplete()
{
    boolean             ret;
    WhsrfPassthrough    pass        = controller.parmSessionState().parmPass();

    if (pass.lookupStr(ProcessGuideDataTypeNames::AVALicensePlateId)
     && pass.lookupStr(ProcessGuideDataTypeNames::AVAContainerType))
    {
        ret = true;
    }

    return ret;
}
